    // Map from folder path to map of resource key to location
    // Actually, since we clear per folder, we can just use one map and clear it in beforeCheckFolder
    private final Map<String, Location> mResources = new HashMap<>();

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void beforeCheckFolder(Context context) {
        mResources.clear();
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String name = element.getAttribute("name");
        if (name == null || name.isEmpty()) {
            return;
        }

        String tag = element.getTagName();
        String type;
        if ("item".equals(tag)) {
            type = element.getAttribute("type");
            if (type == null || type.isEmpty()) {
                return;
            }
        } else {
            type = tag;
        }

        // Normalize name: dots are treated as underscores in resource names
        String normalizedName = name.replace('.', '_');
        String key = type + "/" + normalizedName;

        Location location = context.getLocation(element.getAttributeNode("name"));
        Location existing = mResources.put(key, location);
        if (existing != null) {
            // Report duplicate
            location.setSecondary(existing);
            context.report(ISSUE, location, String.format("Duplicate resource name \"%s\"", name));
        }
    }
}
